const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-79.887682, -2.306934]);
  const roi = point.buffer(1000); // 1km radius
  const targetDate = '2024-08-29';

  // 2. Data Acquisition & Check
  const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .sort('CLOUD_COVER');

  const imageCount = landsat8.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    // Try expanding date range
    const expandedCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate('2024-08-20', '2024-09-10')
      .sort('CLOUD_COVER');

    const expandedCount = expandedCol.size().getInfo();
    console.log(`Expanded search images: ${expandedCount}`);

    if (expandedCount === 0) {
      console.log("No Landsat 8 imagery available.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Cloud masking function
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);

    const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);

    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  // 3. Processing
  const collection = imageCount > 0 ? landsat8 : 
    ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate('2024-08-20', '2024-09-10')
      .sort('CLOUD_COVER');

  const image = collection.first();
  const masked = maskL8sr(image);

  const cloudCover = image.get('CLOUD_COVER').getInfo();
  console.log(`Cloud cover: ${cloudCover}%`);

  // Calculate indices
  const nir = masked.select('SR_B5');
  const red = masked.select('SR_B4');
  const green = masked.select('SR_B3');
  const swir1 = masked.select('SR_B6');

  const ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');
  const ndwi = green.subtract(nir).divide(green.add(nir)).rename('NDWI');
  const mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');

  const indices = masked.addBands([ndvi, ndwi, mndwi]);

  // Check valid pixels
  const pixelCount = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  const stats = indices.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  });

  const ndviMean = stats.get('NDVI').getInfo();
  const ndwiMean = stats.get('NDWI').getInfo();
  const mndwiMean = stats.get('MNDWI').getInfo();

  // 5. Validation & Final Answer
  if (ndviMean === null || ndwiMean === null || mndwiMean === null) {
    console.log("Calculation returned null values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (ndviMean < -1 || ndviMean > 1 || ndwiMean < -1 || ndwiMean > 1) {
    console.log("Invalid index values (out of range).");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`NDVI mean: ${ndviMean.toFixed(3)}`);
  console.log(`NDWI mean: ${ndwiMean.toFixed(3)}`);
  console.log(`MNDWI mean: ${mndwiMean.toFixed(3)}`);

  // Classification logic:
  // Shrimp ponds: High MNDWI (>0.0), moderate NDVI (0.0-0.4)
  // Mangrove forest: High NDVI (>0.5), negative MNDWI (<-0.1)

  const isShrimp = mndwiMean > 0.0 && ndviMean < 0.5;
  const isMangrove = ndviMean > 0.5 && mndwiMean < 0.0;

  console.log(`Classification: Shrimp=${isShrimp}, Mangrove=${isMangrove}`);

  if (isShrimp && !isMangrove) {
    console.log("Area predominantly shrimp farming.");
    console.log("<answer>A</answer>");
  } else if (isMangrove && !isShrimp) {
    console.log("Area predominantly mangrove forest.");
    console.log("<answer>B</answer>");
  } else if (mndwiMean > -0.1 && ndviMean < 0.5) {
    console.log("Mixed/aquatic characteristics favor shrimp.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Area predominantly mangrove forest.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
